<template>
  <div class="blog-admin"><div class="blog-admin__head"><div><h1>Блог</h1><p>Статьи, категории и публикации</p></div><router-link to="/blog/new" class="blog-admin__primary">+ Новая статья</router-link></div>
    <div class="blog-admin__tabs"><button :class="{ active: tab === 'posts' }" @click="tab = 'posts'">Статьи</button><button :class="{ active: tab === 'categories' }" @click="tab = 'categories'">Категории</button></div>
    <template v-if="tab === 'posts'"><div class="blog-admin__filters"><input v-model="search" placeholder="Поиск по названию или URL" aria-label="Поиск статей"><select v-model="status"><option value="">Все статусы</option><option value="DRAFT">Черновики</option><option value="PUBLISHED">Опубликованы</option></select><select v-model="categoryFilter"><option value="">Все категории</option><option v-for="cat in categories" :key="cat.id" :value="cat.id">{{ cat.name }}</option></select></div><p v-if="error" class="blog-admin__error">{{ error }}</p><div class="blog-admin__posts"><div v-for="post in filteredPosts" :key="post.id" class="blog-admin__post"><img v-if="post.cover" :src="post.cover" :alt="post.coverAlt"><div class="blog-admin__post-copy"><span :class="['blog-admin__status', post.status === 'PUBLISHED' ? 'is-live' : '']">{{ post.status === 'PUBLISHED' ? 'Опубликована' : 'Черновик' }}</span><strong>{{ post.title || 'Без названия' }}</strong><small>{{ post.category?.name || 'Без категории' }} · {{ new Date(post.updatedAt).toLocaleDateString('ru-RU') }} <span v-if="post.featured">· ★ Рекомендуемая</span></small></div><router-link :to="`/blog/${post.id}/edit`" class="blog-admin__edit">Редактировать →</router-link><button type="button" class="blog-admin__delete" :aria-label="`Удалить статью ${post.title}`" @click="removePost(post)">Удалить</button></div><p v-if="!filteredPosts.length && !error" class="blog-admin__empty">Статей пока нет. Создайте первую публикацию.</p></div></template>
    <template v-else><form class="blog-admin__category-form" @submit.prevent="saveCategory"><input v-model="categoryName" required placeholder="Название новой категории" aria-label="Название категории"><button class="blog-admin__primary">{{ editingCategory ? 'Сохранить' : '+ Добавить категорию' }}</button><button v-if="editingCategory" type="button" @click="resetCategory">Отмена</button></form><p v-if="error" class="blog-admin__error">{{ error }}</p><div v-for="cat in categories" :key="cat.id" class="blog-admin__category"><span>{{ cat.name }} <small>/{{ cat.slug }}</small></span><div><button @click="editCategory(cat)">Изменить</button><button @click="removeCategory(cat)" class="is-danger">Удалить</button></div></div></template>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import axios from 'axios'
import './blogAdmin.css'
import './blogAdminExtras.css'
const tab = ref('posts'), posts = ref([]), categories = ref([]), search = ref(''), status = ref(''), categoryFilter = ref(''), error = ref(''), categoryName = ref(''), editingCategory = ref(null)
const filteredPosts = computed(() => posts.value.filter(post => (!search.value || `${post.title} ${post.slug}`.toLowerCase().includes(search.value.toLowerCase())) && (!status.value || post.status === status.value) && (!categoryFilter.value || post.categoryId === Number(categoryFilter.value))))
async function load() { try { const [p, c] = await Promise.all([axios.get('/api/blog/admin/posts'), axios.get('/api/blog/categories')]); posts.value = p.data; categories.value = c.data } catch { error.value = 'Не удалось загрузить блог' } }
async function saveCategory() { error.value = ''; try { if (editingCategory.value) await axios.put(`/api/blog/admin/categories/${editingCategory.value.id}`, { name: categoryName.value }); else await axios.post('/api/blog/admin/categories', { name: categoryName.value }); resetCategory(); await load() } catch (err) { error.value = err.response?.data?.error || 'Не удалось сохранить категорию' } }
function editCategory(cat) { editingCategory.value = cat; categoryName.value = cat.name }
function resetCategory() { editingCategory.value = null; categoryName.value = '' }
async function removeCategory(cat) { if (!confirm(`Удалить категорию «${cat.name}»? Статьи останутся без категории.`)) return; try { await axios.delete(`/api/blog/admin/categories/${cat.id}`); await load() } catch { error.value = 'Не удалось удалить категорию' } }
async function removePost(post) { if (!confirm(`Удалить статью «${post.title || 'Без названия'}»? Восстановить её будет нельзя.`)) return; try { await axios.delete(`/api/blog/admin/posts/${post.id}`); await load() } catch { error.value = 'Не удалось удалить статью' } }
onMounted(load)
</script>
